Code:
```python
content = file_content['content']
lines = content.split('\n')
songs = []

for line in lines:
    line = line.strip()
    if not line or line.startswith('#'):
        continue
    if line.startswith('- '):
        song_info = line[2:].strip()
        if ',' in song_info:
            title, artists = song_info.split(',', 1)
            title = title.strip()
            artists = [artist.strip() for artist in artists.split(',')]
            songs.append({
                'title': title,
                'artists': artists
            })
        else:
            # Handle cases where artists are not specified
            title = song_info.strip()
            songs.append({
                'title': title,
                'artists': []
            })

print(songs)
